  "confidence": 0.96,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["J11"],
      "pins": ["J11.1"],
      "nets": ["5V_switched", "RC_SBUS"],
      "observed": "J11 pin 1 appears as a node on both the 5V_switched power net and the RC_SBUS signal net. RC_SBUS also connects to J19 pins 3/4 and through R22 to the gate of Q5, so this places the SBUS signal net directly on the switched 5V rail.",
      "expected": "5V_switched should be a switched 5V supply net (for example for the WS2812/LED connector pins) and RC_SBUS should remain a separate SBUS signal net connected to J19 and the SBUS input conditioning circuitry, not shorted to 5V_switched.",
      "evidence": [
        {"source": "netlist", "quote": "(net (code \"51\") (name \"5V_switched\")"},
        {"source": "netlist", "quote": "(node (ref \"J11\") (pin \"1\") (pinfunction \"Pin_1\") (pintype \"passive\"))"},
        {"source": "netlist", "quote": "(net (code \"172\") (name \"RC_SBUS\")"},
        {"source": "netlist", "quote": "(node (ref \"J11\") (pin \"1\") (pinfunction \"Pin_1\") (pintype \"passive\"))"}
      ],
      "impact": "The SBUS input is tied to switched 5V. R22 would pull Q5's gate high, likely turning Q5 on and holding SBUS_RX low, while the SBUS connector pins see 5V instead of a valid signal. The RC/SBUS interface would not operate correctly and the SBUS line may be overloaded.",
      "confidence": 0.96
    }
  ],
  "summary": "The design files contain a clear connectivity anomaly: J11 pin 1 is listed on both 5V_switched and RC_SBUS, shorting the SBUS signal net to the switched 5V rail."
}

